int main() {
    double prev, px;
    if (!(std::cin >> prev)) {
        std::cout << "Need two prices\n";
        return 0;
    }
    bool any = false;
    double worst = 0.0;
    while (std::cin >> px) {
        double r = (px - prev) / prev;
        if (!any || r < worst) worst = r;
        any = true;
        prev = px;
    }
    if (!any) {
        std::cout << "Need two prices\n";
        return 0;
    }
    std::cout << std::fixed << std::setprecision(2)
              << "Worst day: " << worst * 100 << "%\n";
    return 0;
}

