#include <stdexcept>

class CreditLine {
public:
    explicit CreditLine(double limit)
        : limit_(limit), used_(0.0) {
        if (!(limit_ > 0))
            throw std::invalid_argument("bad limit");
    }
    void draw(double x) {
        if (!(x > 0) || used_ + x > limit_)
            throw std::invalid_argument("bad draw");
        used_ += x;
    }
    void repay(double x) {
        if (!(x > 0) || x > used_)
            throw std::invalid_argument("bad repayment");
        used_ -= x;
    }
    void set_limit(double limit) {
        if (!(limit > 0) || limit < used_)
            throw std::invalid_argument("bad limit");
        limit_ = limit;
    }
    double used() const { return used_; }
    double headroom() const { return limit_ - used_; }

private:
    double limit_;
    double used_;
};

