// Supplied: Grid, with pnl and the counter Grid::live.
// Its destructor is private: only std::unique_ptr may
// delete a Grid.
double worst_pnl(const std::vector<double>& shocks,
                 double qty, double spot, double limit) {
    Grid* g = new Grid(shocks.size());
    if (shocks.empty()) return 0.0;            // leaks g
    for (std::size_t i = 0; i < shocks.size(); ++i) {
        g->pnl[i] = qty * spot * shocks[i];
        if (g->pnl[i] < -limit) return -limit;  // leaks g
    }
    double worst = *std::min_element(g->pnl.begin(),
                                     g->pnl.end());
    // delete g;  would free it, but no longer compiles
    return worst;
}

