double worst_pnl(const std::vector<double>& shocks,
                 double qty, double spot, double limit) {
    auto g = std::make_unique<Grid>(shocks.size());
    if (shocks.empty()) return 0.0;
    for (std::size_t i = 0; i < shocks.size(); ++i) {
        g->pnl[i] = qty * spot * shocks[i];
        if (g->pnl[i] < -limit) return -limit;  // stop-loss
    }
    return *std::min_element(g->pnl.begin(),
                             g->pnl.end());
}

