#include <algorithm>
#include <numeric>
#include <string>
#include <vector>

std::vector<int> ranked_ids(std::vector<Fill> fills) {
    std::sort(fills.begin(), fills.end(),
              [](const Fill& a, const Fill& b) {
                  if (a.venue != b.venue)
                      return a.venue < b.venue;
                  return a.qty > b.qty;
              });
    std::vector<int> ids;
    for (const Fill& f : fills) ids.push_back(f.id);
    return ids;
}

double notional_at_least(const std::vector<Fill>& fills,
                         int min_qty) {
    return std::accumulate(
        fills.begin(), fills.end(), 0.0,
        [min_qty](double total, const Fill& f) {
            return f.qty >= min_qty ? total + f.qty * f.px
                                    : total;
        });
}

