public:
    virtual ~Payoff() = default;
    virtual double operator()(double spot) const = 0;
};
class Call : public Payoff {
public:
    explicit Call(double strike) : strike_(strike) {}
    double operator()(double spot) const override { return std::max(spot - strike_, 0.0); }
private:
    double strike_;
};
class Put : public Payoff {
public:
    explicit Put(double strike) : strike_(strike) {}
    double operator()(double spot) const override { return std::max(strike_ - spot, 0.0); }
private:
    double strike_;
};

