class Straddle : public Payoff {
public:
    explicit Straddle(double strike) : strike_(strike) {}
    double operator()(double spot) const override {
        return 0.0;  // pays |spot - strike|
    }
private:
    double strike_;
};

double up_and_out(const Payoff& payoff, double s,
                  double barrier, double u, double growth,
                  int n) {
    // d = 1 / u, q = (growth - d) / (u - d): refuse q
    // outside (0, 1). One vector of n + 1 values: the
    // leaves, then n steps back. A node whose spot
    // s * u^(2j - i) is at or above the barrier is worth 0.
    return 0.0;
}

