#include <algorithm>
#include <cmath>
#include <stdexcept>
#include <vector>

class Straddle : public Payoff {
public:
    explicit Straddle(double strike) : strike_(strike) {}
    double operator()(double spot) const override {
        return std::abs(spot - strike_);
    }
private:
    double strike_;
};

double up_and_out(const Payoff& payoff, double s,
                  double barrier, double u, double growth,
                  int n) {
    double d = 1.0 / u;
    double q = (growth - d) / (u - d);
    if (!(q > 0.0 && q < 1.0))
        throw std::invalid_argument("q outside (0, 1)");
    std::vector<double> v(n + 1);
    for (int j = 0; j <= n; ++j) {
        double spot = s * std::pow(u, 2 * j - n);
        v[j] = spot >= barrier ? 0.0 : payoff(spot);
    }
    for (int i = n - 1; i >= 0; --i)
        for (int j = 0; j <= i; ++j) {
            double spot = s * std::pow(u, 2 * j - i);
            double hold = q * v[j + 1] + (1 - q) * v[j];
            v[j] = spot >= barrier ? 0.0 : hold / growth;
        }
    return v[0];
}

