struct ZqTest { const char* name; void (*fn)(); };
std::vector<ZqTest>& zq_registry() { static std::vector<ZqTest> t; return t; }
struct ZqAdd { ZqAdd(const char* n, void (*f)()) { zq_registry().push_back({n, f}); } };
int zq_bad = 0;

#define TEST(name) void name(); static ZqAdd name##_zq(#name, name); void name()
#define CHECK(cond) do { if (!(cond)) { ++zq_bad; std::printf("  %s:%d: CHECK(%s) failed\n", __FILE__, __LINE__, #cond); } } while (0)
#define CHECK_CLOSE(a, b, tol) do { double zq_a = (a), zq_b = (b); if (!(std::fabs(zq_a - zq_b) <= (tol))) { ++zq_bad; std::printf("  %s:%d: CHECK_CLOSE(%s, %s, %s) failed: %.10g and %.10g\n", __FILE__, __LINE__, #a, #b, #tol, zq_a, zq_b); } } while (0)

double norm_cdf(double x) { return 0.5 * std::erfc(-x / std::sqrt(2.0)); }
static double zq_d2(double s, double k, double r, double v, double t) {
    return (std::log(s / k) + (r - 0.5 * v * v) * t) / (v * std::sqrt(t));
}
double dcall_ok(double s, double k, double r, double v, double t) { return std::exp(-r * t) * norm_cdf(zq_d2(s, k, r, v, t)); }
double dput_ok(double s, double k, double r, double v, double t) { return std::exp(-r * t) * norm_cdf(-zq_d2(s, k, r, v, t)); }
double dput_alt(double s, double k, double r, double v, double t) { return std::exp(-r * t) * 0.5 * std::erfc(zq_d2(s, k, r, v, t) / std::sqrt(2.0)); }
double dcall_alt(double s, double k, double r, double v, double t) { return std::exp(-r * t) - dput_alt(s, k, r, v, t); }
double dcall_d1(double s, double k, double r, double v, double t) { return std::exp(-r * t) * norm_cdf(zq_d2(s, k, r, v, t) + v * std::sqrt(t)); }
double dcall_nodisc(double s, double k, double r, double v, double t) { return norm_cdf(zq_d2(s, k, r, v, t)); }
double dput_nodisc(double s, double k, double r, double v, double t) { return norm_cdf(-zq_d2(s, k, r, v, t)); }
static double zq_d2_sig(double s, double k, double r, double v, double t) { return (std::log(s / k) + (r - 0.5 * v * v) * t) / v; }
double dcall_sig(double s, double k, double r, double v, double t) { return std::exp(-r * t) * norm_cdf(zq_d2_sig(s, k, r, v, t)); }
double dput_sig(double s, double k, double r, double v, double t) { return std::exp(-r * t) * norm_cdf(-zq_d2_sig(s, k, r, v, t)); }
typedef double (*Pricer)(double, double, double, double, double);
Pricer digital_call = dcall_ok, digital_put = dput_ok;

