TEST(test_digital_parity) {
    // call + put pays £1 for sure: worth exp(-rT) today
    for (double t : {0.25, 1.0, 2.0}) {
        double c = digital_call(100, 105, 0.03, 0.25, t);
        double p = digital_put(100, 105, 0.03, 0.25, t);
        CHECK_CLOSE(c + p, std::exp(-0.03 * t), 1e-12);
    }
}

TEST(test_near_expiry) {
