    // almost nothing out of the money, almost exp(-rT) in
    double t = 1.0 / 365;
    CHECK(digital_call(100, 105, 0.03, 0.25, t) < 1e-3);
    CHECK(digital_call(110, 105, 0.03, 0.25, t) > 0.99);
